def minutes(apps, schema_editor):
    for p in apps.get_model("core", "Plan").objects.all():
        name = p.name.lower().replace(" plan", "").strip()
        if name in TEST_MINUTES: p.call_minutes = TEST_MINUTES[name]
        elif p.daily_call_seconds < 0: p.call_minutes = -1
        else: p.call_minutes = (p.daily_call_seconds + 59) // 60
        p.save(update_fields=["call_minutes"])


